const tenantId = $input.first().json.body.tenant_id;
const eventType = $input.first().json.body.event_type;
const payload = $input.first().json.body.payload;

const configs = {
  tenant_a: {
    tenant_id: "tenant_a",
    name: "E-commerce SMB",
    error_mode: "continue",
    data_handling: "standard",
    email: {
      enabled: true,
      from_name: "TenantA Store",
      templates: {
        cart_abandoned: "tmpl_001",
        new_order: "tmpl_002",
        refund_requested: "tmpl_003"
      }
    },
    sheet_log: {
      enabled: true,
      sheet_id: "sheet_tenant_a"
    },
    slack: {
      enabled: false
    },
    crm: {
      enabled: false
    },
    audit: {
      enabled: false
    }
  },
  tenant_b: {
    tenant_id: "tenant_b",
    name: "B2B SaaS",
    error_mode: "block",
    data_handling: "standard",
    email: {
      enabled: true,
      from_name: "TenantB",
      templates: {
        trial_signup: "tmpl_010",
        upgrade: "tmpl_011",
        churn_signal: "tmpl_012"
      }
    },
    sheet_log: {
      enabled: false
    },
    slack: {
      enabled: true,
      channel: "#new-trials"
    },
    crm: {
      enabled: true,
      record_type: "Lead"
    },
    audit: {
      enabled: false
    }
  },
  tenant_c: {
    tenant_id: "tenant_c",
    name: "Healthcare Provider",
    error_mode: "block",
    data_handling: "pii_masked",
    email: {
      enabled: true,
      from_name: "HealthcareCo",
      templates: {
        appointment_reminder: "tmpl_020",
        intake_completed: "tmpl_021"
      }
    },
    sheet_log: {
      enabled: false
    },
    slack: {
      enabled: false
    },
    crm: {
      enabled: false
    },
    audit: {
      enabled: true
    }
  }
};

const config = configs[tenantId];

if (!config) {
  throw new Error(`Unknown tenant_id: ${tenantId}`);
}

return [{
  json: {
    tenant_config: config,
    event_type: eventType,
    payload: payload
  }
}];

