const parsed = JSON.parse($input.first().json.output);
const tenantConfig = $('Tenant Config Lookup').first().json.tenant_config;
const payload = $('Tenant Config Lookup').first().json.payload;

return [{
  json: {
    ...parsed,
    pii_required: tenantConfig.data_handling === 'pii_masked',
    original_payload: payload
  }
}];
